extern "C" float sqrtf(float);
asm(".equ sqrtf, 0x003C7058");

class vector3d
{
public:
    float x, y, z;

    vector3d() {}
    vector3d(float a, float b, float c) : x(a), y(b), z(c) {}

    vector3d operator-() const { return vector3d(-x, -y, -z); }
    vector3d operator+(const vector3d &v) const { return vector3d(x + v.x, y + v.y, z + v.z); }
    vector3d operator*(float s) const { return vector3d(x * s, y * s, z * s); }

    void normalize()
    {
        float len2 = x * x + y * y + z * z;
        if (len2 > 1.0e-10f)
        {
            float inv = 1.0f / sqrtf(len2);
            x *= inv;
            y *= inv;
            z *= inv;
        }
    }
};

inline vector3d operator*(float s, const vector3d &v) { return v * s; }

extern vector3d XVEC;
extern vector3d ZVEC;
extern float tube_tilt_towards_beach;
asm(".equ XVEC, 0x00554448");
asm(".equ ZVEC, 0x00554468");
asm(".equ tube_tilt_towards_beach, 0x00424C70");

class po
{
public:
    vector3d non_affine_slow_xform(const vector3d &v) const;
};
asm(".equ non_affine_slow_xform__C2poRC8vector3d, 0x003483A8");

class entity
{
    char padding[0x50];
    po absolute_po;
public:
    const po &get_abs_po() const { return absolute_po; }
};

class board_controller
{
    entity *my_board;
public:
    vector3d GetForwardDir() const { return my_board->get_abs_po().non_affine_slow_xform(ZVEC); }
};

class spin_controller
{
public:
    void SetSpinType(int type, float angle, vector3d axis, float rate);
};
asm(".equ SetSpinType__15spin_controllerifG8vector3df, 0x0020C058");

enum { SPIN_FLOATER = 5 };

class kellyslater_controller
{
    char padding0[0xd50];
    board_controller my_board_controller;
    char padding1[0xbe4];
    spin_controller spin_ctrl;
public:
    void Tube_Align(float z_offset, float spin_rate);
};

void kellyslater_controller::Tube_Align(float z_offset, float spin_rate)
{
	vector3d alignment_vec;

	z_offset += tube_tilt_towards_beach;  //  The default offset from the Z-axis.

	if ( my_board_controller.GetForwardDir().x > 0)
		alignment_vec = XVEC + (z_offset * ZVEC);
	else
		alignment_vec = -XVEC + (z_offset * ZVEC);

	alignment_vec.normalize();

	spin_ctrl.SetSpinType(SPIN_FLOATER, 0.0f, alignment_vec, spin_rate);
}
